mapper.select:
SELECT o.id, o.order_no, o.buyer_id, o.seller_id, o.book_id, o.book_title, o.book_price, o.quantity, o.total_amount, o.address, o.status, o.pay_time, o.ship_time, o.finish_time, o.create_time, o.update_time, b.nickname AS buyer_name, s.nickname AS seller_name FROM orders o LEFT JOIN user b ON o.buyer_id = b.id LEFT JOIN user s ON o.seller_id = s.id
AND o.buyer_id = #{buyerId}
AND o.seller_id = #{sellerId}
AND o.status = #{status}
ORDER BY o.create_time DESC

mapper.update:
UPDATE orders
status = #{targetStatus}, pay_time = #{payTime}, ship_time = #{shipTime}, finish_time = #{finishTime},
WHERE id = #{id} AND status = #{expectStatus}
